import os, re, subprocess, tempfile, zipfile, xml.etree.ElementTree as ET, glob
from pathlib import Path

base = Path('/root/papers/all')
files = [p for p in base.iterdir() if p.is_file()]

categories = {
    'LLM': [
        'large language model','language model','llm','gpt','transformer','attention','pretrain','pre-training',
        'instruction tuning','rlhf','prompt','token','context window','foundation model','chatgpt','rag','retrieval augmented'
    ],
