        'trapped ion','ion trap','paul trap','linear trap','quantum computing','quantum computer','quantum gate','qubit','qubits',
        'quantum logic','entanglement','rydberg','laser cooling','mølmer','mølmer–sørensen','sørensen','ion chain','quantum processor'
    ],
    'black_hole': [
        'black hole','event horizon','hawking','accretion','singularity','kerr','schwarzschild','gravitational wave',
        'black-hole','supermassive','ergosphere','no-hair','ads/cft','bekenstein','hawking radiation'
    ],
    'DNA': [
        'dna','genome','genomics','genetic','gene','chromosome','nucleotide','sequencing','crispr','polymerase','double helix',
        'rna','transcription','epigenetic','mutation','base pair','base-pair','helix'
    ],
    'music_history': [
        'music history','music','composer','symphony','opera','jazz','rock','baroque','renaissance','classical','genre',
        'musical','concert','orchestra','sonata','choral','folk','hip hop','hip-hop'
    ]
}

# preprocess patterns
patterns = {cat:[re.compile(r'\b'+re.escape(k.lower())+r'\b') for k in kws] for cat,kws in categories.items()}


def extract_text_pdf(path):
    with tempfile.NamedTemporaryFile(suffix='.txt', delete=False) as tmp:
        tmp_path = tmp.name
    try:
        # extract first 2 pages to keep it fast
        subprocess.run(['pdftotext','-f','1','-l','2','-layout',str(path),tmp_path], check=False, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
        try:
            with open(tmp_path,'r',errors='ignore') as f:
                return f.read(12000)
        except FileNotFoundError:
            return ''
    finally:
        try:
            os.remove(tmp_path)
        except FileNotFoundError:
            pass


def extract_text_docx(path):
    try:
        with zipfile.ZipFile(path) as z:
            text = ''
            for name in z.namelist():
                if name.startswith('word/') and name.endswith('.xml'):
                    try:
                        data = z.read(name)
                    except Exception:
                        continue
                    try:
                        root = ET.fromstring(data)
                    except Exception:
                        continue
                    # Word uses w:t for text
                    for t in root.iter():
                        if t.tag.endswith('}t') and t.text:
                            text += t.text + ' '
            return text[:12000]
    except Exception:
        return ''


def extract_text_pptx(path):
    try:
        with zipfile.ZipFile(path) as z:
            text = ''
            for name in z.namelist():
                if name.startswith('ppt/slides/slide') and name.endswith('.xml'):
                    try:
                        data = z.read(name)
                    except Exception:
                        continue
                    try:
                        root = ET.fromstring(data)
                    except Exception:
                        continue
                    for t in root.iter():
                        if t.tag.endswith('}t') and t.text:
                            text += t.text + ' '
            return text[:12000]
    except Exception:
        return ''


def extract_text(path):
    ext = path.suffix.lower()
    if ext == '.pdf':
        return extract_text_pdf(path)
    if ext == '.docx':
        return extract_text_docx(path)
    if ext == '.pptx':
        return extract_text_pptx(path)
    return ''


def score_text(text):
    text_l = text.lower()
    scores = {}
    for cat, pats in patterns.items():
        s = 0
        for pat in pats:
            s += len(pat.findall(text_l))
        scores[cat] = s
    return scores

results = []
for p in sorted(files):
    text = extract_text(p)
    scores = score_text(text)
    best = max(scores, key=scores.get)
    if scores[best] == 0:
        best = 'music_history'  # fallback per instruction
    results.append((p.name, best, scores))

# summary counts
from collections import Counter
cnt = Counter([r[1] for r in results])
print('Counts:')
for k in ['LLM','trapped_ion_and_qc','black_hole','DNA','music_history']:
    print(k, cnt.get(k,0))

# show low-confidence (ties or small score)
print('\nLow/zero-score cases:')
for name, best, scores in results:
    max_score = scores[best]
    # consider low if max <=1
    if max_score <= 1:
        print(name, best, scores)
